<section class="wrap workspace" data-workspace="<?= $path==='/admin'?'admin':'client' ?>"><div class="workspace-head"><div><p class="eyebrow">DATUM / SECURE WORKSPACE</p><h1><?= e($title) ?></h1></div><button id="logout" class="button secondary" hidden>Sign out</button></div><p id="workspace-message" role="status" aria-live="polite"></p><form id="login-form" class="panel narrow"><h2>Welcome back.</h2><p>Use the account provisioned for your project.</p><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Sign in ↗</button></form><section id="mfa-panel" class="panel narrow" hidden><h2>Two-factor verification</h2><div id="mfa-enrollment"></div><form id="mfa-form"><label>Authenticator code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></label><button class="button">Verify</button></form></section><div id="workspace-body" hidden><nav id="workspace-nav" class="tabs" aria-label="Workspace sections"></nav><div id="workspace-content"></div></div></section>
